-- 세트 84: HAProxy 운영 심화: 로그 읽기, 요청 제한, 차단, URI 분산
-- 기본기 사다리(docs/specs/spec_foundations_ladder.md). 정답·해설은 서버만 안다. 실습 문제의 grade_cmd 는 checks 의 조건을 && 로 이은 것과 같다.
INSERT INTO quest (quest_set_id, order_index, title, description, hint, solution, setup_cmd, grade_cmd, kind, choices, answer_index, explanation, answer_spec, template, checks, docs) VALUES
  (84, 1, '로그 타이밍으로 병목 찾기 (큐 대기)', 'HAProxy 로그의 타이밍 필드(`Tq/Tw/Tc/Tr/Tt`)에서 **`Tw`(큐 대기 시간)가 길게** 나옵니다. 가장 가능성 높은 원인은 무엇일까요?', 'Tw 는 서버에 배정받기 전에 queue 에서 기다린 시간입니다.', NULL, NULL, '[]', 'choice', '["백엔드 애플리케이션의 처리가 느리다", "백엔드 서버의 `maxconn` 이 부족해 요청이 queue 에서 기다리고 있다", "클라이언트의 네트워크가 느리다", "DNS 가 느리다"]', 1, '`Tw` 가 크면 서버가 이미 최대 연결로 차 있다는 신호라 `maxconn` 조정이나 서버 증설을 봅니다. 앞서 배운 queue 와 `timeout queue`(초과하면 503)와 연결됩니다.', NULL, NULL, NULL, NULL),
  (84, 2, '로그 타이밍으로 병목 찾기 (응답 시간)', '`Tw`, `Tc` 는 정상인데 **`Tr`(서버 응답 시간)** 만 길게 나옵니다. 어디를 먼저 볼까요?', 'Tr 은 서버가 연결을 받은 뒤 응답을 내려보내기까지의 시간입니다.', NULL, NULL, '[]', 'choice', '["HAProxy 의 `bind` 포트", "클라이언트 브라우저 설정", "HAProxy 의 `global` maxconn", "백엔드 애플리케이션의 처리 자체(쿼리, 외부 호출 등)"]', 3, '`Tc` 가 길면 네트워크나 서버 accept 지연, `Tr` 이 길면 앱이 느린 것입니다. 로그 한 줄로 "어느 구간이 느린가"를 나눠서 볼 수 있는 것이 HAProxy 로그의 장점입니다.', NULL, NULL, NULL, NULL),
  (84, 3, '요청 제한과 연결 제한의 차이', '"10초에 100번 넘게 요청하면 차단"은 **어느 쪽**일까요? 반대로 "동시에 20개를 넘게 연결하면 차단"은 어느 쪽일까요?', '하나는 시간 기반, 하나는 현재 상태 기반입니다.', NULL, NULL, '[]', 'choice', '["앞의 것은 Rate Limiting(시간당 요청 수), 뒤의 것은 Connection Limiting(현재 동시 연결 수)이다", "앞의 것이 Connection Limiting, 뒤의 것이 Rate Limiting 이다", "둘 다 같은 기능이다", "둘 다 서버 maxconn 설정이다"]', 0, '연결을 맺고 오래 붙잡는 공격에는 Connection Limiting, 빠르게 요청을 반복하는 공격에는 Rate Limiting 이 맞습니다. 둘 다 stick-table 에 IP 별 값을 저장해 판단합니다. 서버 `maxconn` 은 전체 상한이고 특정 IP 를 겨냥한 제한이 아닙니다.', NULL, NULL, NULL, NULL),
  (84, 4, 'tcp-request 와 http-request', '연결 수 제한에 `http-request` 대신 **`tcp-request connection`** 을 쓰는 이유는 무엇일까요?', 'HTTP 를 파싱하기 전 단계에서 판단합니다.', NULL, NULL, '[]', 'choice', '["HTTP 를 지원하지 않는 서버에서만 쓸 수 있다", "더 느려서 안전하다", "HTTP 요청을 파싱하기 **전**의 TCP 단계에서 판단해 더 이른 시점에 차단할 수 있다", "로그를 남기지 않기 위해서이다"]', 2, 'tcp 단계 규칙은 연결 직후 적용되어 비용이 적고 이른 차단이 가능하지만 경로·헤더는 볼 수 없습니다. 경로·헤더 기준 차단은 `http-request` 로 합니다.', NULL, NULL, NULL, NULL),
  (84, 5, 'balance uri 의 용도', '`balance uri` 는 어떤 서버를 고를까요? 그리고 어디에 유용할까요?', 'URI 를 해싱하면 같은 경로는 어느 서버로 갈까요?', NULL, NULL, '[]', 'choice', '["요청마다 서버를 번갈아 간다", "같은 URI 는 항상 같은 서버로 간다. 같은 콘텐츠를 같은 캐시 서버가 맡게 해 **캐시 서버 앞단**에서 유용하다", "클라이언트 IP 로 고정한다", "응답이 가장 빠른 서버를 고른다"]', 1, '`source` 는 클라이언트 IP, `uri` 는 요청 경로를 해싱합니다. 캐시가 서버마다 따로 쌓이므로 같은 경로가 같은 서버로 가면 적중률이 올라갑니다. 서버 수가 바뀌면 매핑이 달라진다는 한계는 source 와 같습니다.', NULL, NULL, NULL, NULL),
  (84, 6, '로그가 남는 곳', '컨테이너 환경에서 HAProxy 로그를 syslog 없이 확인하는 가장 간단한 방법은 무엇일까요? (HAProxy 2.x)', '로그 대상을 표준 출력으로 지정할 수 있습니다.', NULL, NULL, '[]', 'choice', '["로그는 반드시 syslog 서버가 있어야만 볼 수 있다", "로그 기능은 컨테이너에서 쓸 수 없다", "`/etc/hosts` 에 로그 경로를 적는다", "`log stdout format raw local0` 처럼 표준 출력으로 내보내고 컨테이너 로그로 수집한다"]', 3, '전통적으로는 `log /dev/log local0` 으로 syslog 에 보내지만, 컨테이너에서는 stdout 으로 내보내 `docker logs` 나 로그 수집기가 가져가게 하는 것이 일반적입니다. HTTP 로그는 `option httplog` 를 켜야 요청 줄과 타이밍이 나옵니다.', NULL, NULL, NULL, NULL),
  (84, 7, '429 와 403 의 의미', '요청 제한에 걸린 클라이언트에게 돌려주는 상태 코드 **429** 와, 접근을 금지한 경로에 돌려주는 **403** 의 의미는 무엇일까요?', '각각 "너무 자주"와 "허용되지 않음"입니다.', NULL, NULL, '[]', 'choice', '["429 Too Many Requests: 짧은 시간에 너무 많은 요청, 403 Forbidden: 요청은 이해했지만 접근이 허용되지 않음", "429 는 서버 오류, 403 은 찾을 수 없음", "429 는 찾을 수 없음, 403 은 서버 오류", "둘 다 성공 코드이다"]', 0, '제한은 403 이 아니라 429 로 구분해 주면 클라이언트가 재시도 간격을 조절할 수 있습니다. 5xx 는 서버 오류, 404 는 찾을 수 없음입니다.', NULL, NULL, NULL, NULL),
  (84, 8, '요청 로그를 남기고 읽기', '`/tmp/haproxy.cfg` 에는 로그 설정이 없습니다. HAProxy 가 **요청 로그를 표준 출력**으로 내보내게 설정하고, 실행 결과(표준 출력)를 `/tmp/hp.log` 로 받아서 `curl localhost:8080/x` 를 **3번** 보낸 뒤, 로그에서 `GET` 이 든 줄 수를 `/tmp/cnt.txt` 에 저장하세요.', '찾는 방법: 공식 문서에서 `log stdout format raw` 와 `option httplog`. `global` 에 `log` 줄, `defaults` 에 `log global` 과 `option httplog` 를 둡니다. HAProxy 는 `-D` 없이 실행하되 `nohup haproxy -f ... > /tmp/hp.log 2>&1 &` 로 띄웁니다.
확인: `cat /tmp/hp.log`', 'sed -i ''1i global\\n    log stdout format raw local0 info'' /tmp/haproxy.cfg
sed -i ''s/^    mode http/    mode http\\n    log global\\n    option httplog/'' /tmp/haproxy.cfg
nohup haproxy -f /tmp/haproxy.cfg > /tmp/hp.log 2>&1 &
sleep 1
for i in 1 2 3; do curl -s localhost:8080/x >/dev/null; done
sleep 1
grep -c GET /tmp/hp.log > /tmp/cnt.txt

# 로그 한 줄에서 frontend, backend/server, 타이밍, 상태 코드, 요청 줄을 읽을 수 있다', '["sh", "-c", "nohup etude-httpd 9001 B1 >/dev/null 2>&1 & nohup etude-httpd 9002 B2 >/dev/null 2>&1 & sleep 1 && printf ''%s\\\\n'' ''defaults'' ''    mode http'' ''    timeout connect 5s'' ''    timeout client 30s'' ''    timeout server 30s'' ''frontend web'' ''    bind *:8080'' ''    default_backend app'' ''backend app'' ''    server s1 127.0.0.1:9001 check'' > /tmp/haproxy.cfg"]', '["sh", "-c", "( haproxy -c -f /tmp/haproxy.cfg >/dev/null 2>&1 ) && ( pgrep haproxy >/dev/null ) && ( [ \\"$(grep -c GET /tmp/hp.log)\\" -ge 3 ] ) && ( grep -qE \\"app/s1 .* 200 \\" /tmp/hp.log ) && ( [ \\"$(cat /tmp/cnt.txt)\\" = \\"$(grep -c GET /tmp/hp.log)\\" ] )"]', 'terminal', NULL, NULL, NULL, NULL, NULL, '[{"label": "설정 파일이 문법 검사를 통과한다", "cmd": ["sh", "-c", "haproxy -c -f /tmp/haproxy.cfg >/dev/null 2>&1"]}, {"label": "HAProxy 가 실행 중이다", "cmd": ["sh", "-c", "pgrep haproxy >/dev/null"]}, {"label": "요청 로그가 표준 출력으로 기록되었다 (GET 3줄 이상)", "cmd": ["sh", "-c", "[ \\"$(grep -c GET /tmp/hp.log)\\" -ge 3 ]"]}, {"label": "로그에 상태 코드와 backend/server 가 보인다", "cmd": ["sh", "-c", "grep -qE \\"app/s1 .* 200 \\" /tmp/hp.log"]}, {"label": "기록한 줄 수가 로그의 GET 줄 수와 같다", "cmd": ["sh", "-c", "[ \\"$(cat /tmp/cnt.txt)\\" = \\"$(grep -c GET /tmp/hp.log)\\" ]"]}]', '[{"title": "HAProxy 공식 문서", "url": "https://docs.haproxy.org/2.4/configuration.html"}]'),
  (84, 9, '경로 차단하기 (403)', '`/admin` 으로 시작하는 요청은 **403 Forbidden** 으로 막고, 나머지 요청은 정상 처리되게 설정한 뒤 HAProxy 를 실행하세요. `/admin/login` 요청의 상태 코드를 `/tmp/admin.txt` 에, `/` 요청의 상태 코드를 `/tmp/root.txt` 에 저장하세요.', '찾는 방법: 공식 문서에서 `http-request deny` 와 `path_beg`. frontend 안에 `acl 이름 path_beg /경로` 와 `http-request deny deny_status 403 if 이름` 을 씁니다. 상태 코드는 `curl -s -o /dev/null -w "%{http_code}"` 입니다.', 'sed -i ''s/^    default_backend app/    acl is_admin path_beg \\/admin\\n    http-request deny deny_status 403 if is_admin\\n    default_backend app/'' /tmp/haproxy.cfg
haproxy -D -f /tmp/haproxy.cfg
curl -s -o /dev/null -w ''%{http_code}'' localhost:8080/admin/login > /tmp/admin.txt
curl -s -o /dev/null -w ''%{http_code}'' localhost:8080/ > /tmp/root.txt

# path_beg : 경로가 해당 문자열로 시작한다', '["sh", "-c", "nohup etude-httpd 9001 B1 >/dev/null 2>&1 & nohup etude-httpd 9002 B2 >/dev/null 2>&1 & sleep 1 && printf ''%s\\\\n'' ''defaults'' ''    mode http'' ''    timeout connect 5s'' ''    timeout client 30s'' ''    timeout server 30s'' ''frontend web'' ''    bind *:8080'' ''    default_backend app'' ''backend app'' ''    server s1 127.0.0.1:9001 check'' > /tmp/haproxy.cfg"]', '["sh", "-c", "( haproxy -c -f /tmp/haproxy.cfg >/dev/null 2>&1 ) && ( pgrep haproxy >/dev/null ) && ( [ \\"$(cat /tmp/admin.txt)\\" = ''403'' ] ) && ( [ \\"$(cat /tmp/root.txt)\\" = ''200'' ] )"]', 'terminal', NULL, NULL, NULL, NULL, NULL, '[{"label": "설정 파일이 문법 검사를 통과한다", "cmd": ["sh", "-c", "haproxy -c -f /tmp/haproxy.cfg >/dev/null 2>&1"]}, {"label": "HAProxy 가 실행 중이다", "cmd": ["sh", "-c", "pgrep haproxy >/dev/null"]}, {"label": "/admin 요청은 403", "cmd": ["sh", "-c", "[ \\"$(cat /tmp/admin.txt)\\" = ''403'' ]"]}, {"label": "일반 요청은 200", "cmd": ["sh", "-c", "[ \\"$(cat /tmp/root.txt)\\" = ''200'' ]"]}]', '[{"title": "HAProxy 공식 문서", "url": "https://docs.haproxy.org/2.4/configuration.html"}]'),
  (84, 10, '요청 빈도 제한하기 (429)', '같은 클라이언트 IP 가 **10초 동안 3번을 넘게** 요청하면 **429** 로 거부되도록 설정하고 실행하세요. 요청을 연달아 6번 보낸 상태 코드를 줄마다 `/tmp/codes.txt` 에 저장하세요. (앞 3번은 200, 뒤 3번은 429 여야 합니다)', '찾는 방법: 공식 문서의 `stick-table`, `track-sc0`, `sc_http_req_rate`. frontend 안에 `stick-table type ip size 1m expire 10s store http_req_rate(10s)`, `http-request track-sc0 src`, `acl too_fast sc_http_req_rate(0) gt 3`, `http-request deny deny_status 429 if too_fast` 구성이 필요합니다.', 'sed -i ''s/^    default_backend app/    stick-table type ip size 1m expire 10s store http_req_rate(10s)\\n    http-request track-sc0 src\\n    acl too_fast sc_http_req_rate(0) gt 3\\n    http-request deny deny_status 429 if too_fast\\n    default_backend app/'' /tmp/haproxy.cfg
haproxy -D -f /tmp/haproxy.cfg
for i in 1 2 3 4 5 6; do curl -s -o /dev/null -w ''%{http_code}\\n'' localhost:8080/; done > /tmp/codes.txt

# stick-table 이 IP 별 최근 10초 요청 수를 기억하고, 기준을 넘으면 거부한다', '["sh", "-c", "nohup etude-httpd 9001 B1 >/dev/null 2>&1 & nohup etude-httpd 9002 B2 >/dev/null 2>&1 & sleep 1 && printf ''%s\\\\n'' ''defaults'' ''    mode http'' ''    timeout connect 5s'' ''    timeout client 30s'' ''    timeout server 30s'' ''frontend web'' ''    bind *:8080'' ''    default_backend app'' ''backend app'' ''    server s1 127.0.0.1:9001 check'' > /tmp/haproxy.cfg"]', '["sh", "-c", "( haproxy -c -f /tmp/haproxy.cfg >/dev/null 2>&1 ) && ( pgrep haproxy >/dev/null ) && ( [ \\"$(cat /tmp/codes.txt)\\" = ''200\\n200\\n200\\n429\\n429\\n429'' ] )"]', 'terminal', NULL, NULL, NULL, NULL, NULL, '[{"label": "설정 파일이 문법 검사를 통과한다", "cmd": ["sh", "-c", "haproxy -c -f /tmp/haproxy.cfg >/dev/null 2>&1"]}, {"label": "HAProxy 가 실행 중이다", "cmd": ["sh", "-c", "pgrep haproxy >/dev/null"]}, {"label": "앞 3번은 200, 뒤 3번은 429", "cmd": ["sh", "-c", "[ \\"$(cat /tmp/codes.txt)\\" = ''200\\n200\\n200\\n429\\n429\\n429'' ]"]}]', '[{"title": "HAProxy 공식 문서", "url": "https://docs.haproxy.org/2.4/configuration.html"}]'),
  (84, 11, '같은 경로를 같은 서버로 보내기 (balance uri)', '`backend app` 은 서버 2대(`s1`=B1, `s2`=B2)를 **번갈아** 씁니다. **같은 경로는 항상 같은 서버**로 가도록 분산 방식을 바꾸고 실행하세요. `/a` 를 4번 요청한 응답을 `/tmp/a.txt` 에, `/b` 를 4번 요청한 응답을 `/tmp/b.txt` 에 저장하세요. (각 파일의 4줄은 모두 같아야 합니다)', '`balance` 줄을 바꿉니다. URI 를 해싱하는 방식의 이름은 공식 문서의 `balance` 항목에 있습니다.
확인: `cat /tmp/a.txt /tmp/b.txt`', 'sed -i ''s/balance roundrobin/balance uri/'' /tmp/haproxy.cfg
haproxy -D -f /tmp/haproxy.cfg
for i in 1 2 3 4; do curl -s localhost:8080/a; echo; done > /tmp/a.txt
for i in 1 2 3 4; do curl -s localhost:8080/b; echo; done > /tmp/b.txt

# uri 해시 : 같은 경로는 같은 서버로 (캐시 서버 앞단에 유용)', '["sh", "-c", "nohup etude-httpd 9001 B1 >/dev/null 2>&1 & nohup etude-httpd 9002 B2 >/dev/null 2>&1 & sleep 1 && printf ''%s\\\\n'' ''defaults'' ''    mode http'' ''    timeout connect 5s'' ''    timeout client 30s'' ''    timeout server 30s'' ''frontend web'' ''    bind *:8080'' ''    default_backend app'' ''backend app'' ''    balance roundrobin'' ''    server s1 127.0.0.1:9001 check'' ''    server s2 127.0.0.1:9002 check'' > /tmp/haproxy.cfg"]', '["sh", "-c", "( haproxy -c -f /tmp/haproxy.cfg >/dev/null 2>&1 ) && ( pgrep haproxy >/dev/null ) && ( grep -q \\"balance uri\\" /tmp/haproxy.cfg ) && ( [ \\"$(sort -u /tmp/a.txt | wc -l)\\" -eq 1 ] && [ \\"$(wc -l < /tmp/a.txt)\\" -eq 4 ] ) && ( [ \\"$(sort -u /tmp/b.txt | wc -l)\\" -eq 1 ] && [ \\"$(wc -l < /tmp/b.txt)\\" -eq 4 ] )"]', 'terminal', NULL, NULL, NULL, NULL, NULL, '[{"label": "설정 파일이 문법 검사를 통과한다", "cmd": ["sh", "-c", "haproxy -c -f /tmp/haproxy.cfg >/dev/null 2>&1"]}, {"label": "HAProxy 가 실행 중이다", "cmd": ["sh", "-c", "pgrep haproxy >/dev/null"]}, {"label": "balance uri 로 설정되어 있다", "cmd": ["sh", "-c", "grep -q \\"balance uri\\" /tmp/haproxy.cfg"]}, {"label": "/a 의 4번 응답이 모두 같다", "cmd": ["sh", "-c", "[ \\"$(sort -u /tmp/a.txt | wc -l)\\" -eq 1 ] && [ \\"$(wc -l < /tmp/a.txt)\\" -eq 4 ]"]}, {"label": "/b 의 4번 응답이 모두 같다", "cmd": ["sh", "-c", "[ \\"$(sort -u /tmp/b.txt | wc -l)\\" -eq 1 ] && [ \\"$(wc -l < /tmp/b.txt)\\" -eq 4 ]"]}]', '[{"title": "HAProxy 공식 문서", "url": "https://docs.haproxy.org/2.4/configuration.html"}]');
